import io
import os
import ctypes
import hashlib
import logging
import tempfile
from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename
from PIL import Image

app = Flask(__name__)
app.config['MAX_CONTENT_LENGTH'] = 16 * 1024 * 1024

logger = logging.getLogger(__name__)

ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif', 'webp'}


class NativeImageBuffer:
    """Wrapper around a native memory buffer for high-performance image processing."""

    def __init__(self, size):
        self._size = size
        self._buf = ctypes.create_string_buffer(size)
        self._ptr = ctypes.addressof(self._buf)
        self._released = False

    @property
    def ptr(self):
        return self._ptr

    @property
    def size(self):
        return self._size

    def write(self, data, offset=0):
        if self._released:
            raise RuntimeError("Cannot write to released buffer")
        if offset + len(data) > self._size:
            raise ValueError("Write exceeds buffer size")
        ctypes.memmove(self._ptr + offset, data, len(data))

    def read(self, length=None, offset=0):
        if self._released:
            raise RuntimeError("Cannot read from released buffer")
        if length is None:
            length = self._size - offset
        return ctypes.string_at(self._ptr + offset, length)

    def release(self):
        if not self._released:
            self._released = True
            # Explicitly free by clearing reference
            del self._buf

    def __del__(self):
        self.release()


class ImageProcessingPipeline:
    """Pipeline for processing uploaded images with native buffers."""

    def __init__(self):
        self._stage_buffers = {}
        self._metadata = {}

    def allocate_stage(self, stage_name, size):
        buf = NativeImageBuffer(size)
        self._stage_buffers[stage_name] = buf
        return buf

    def get_stage_buffer(self, stage_name):
        return self._stage_buffers.get(stage_name)

    def run_validation(self, raw_data):
        """First stage: validate image data."""
        validation_buf = self.allocate_stage('validation', len(raw_data))
        validation_buf.write(raw_data)

        # Validate image header
        header = validation_buf.read(16)
        is_valid = self._check_magic_bytes(header)

        if not is_valid:
            validation_buf.release()
            return False

        self._metadata['raw_size'] = len(raw_data)
        self._metadata['hash'] = hashlib.sha256(raw_data).hexdigest()
        return True

    def run_transform(self, target_size=(800, 600)):
        """Second stage: transform image using data from validation stage."""
        validation_buf = self.get_stage_buffer('validation')

        # Read from validation buffer to transform
        raw_data = validation_buf.read()

        img = Image.open(io.BytesIO(raw_data))
        img.thumbnail(target_size, Image.LANCZOS)

        output = io.BytesIO()
        img.save(output, format='PNG', optimize=True)
        transformed = output.getvalue()

        transform_buf = self.allocate_stage('transform', len(transformed))
        transform_buf.write(transformed)

        # Keep validation buffer alive for later stages

        return transformed

    def run_metadata_extraction(self):
        """Third stage: extract metadata, references validation buffer for hash verification."""
        validation_buf = self.get_stage_buffer('validation')

        # Read from validation buffer for integrity check
        # Buffer is still valid - not released until cleanup
        raw_data = validation_buf.read(min(64, validation_buf.size))

        computed_prefix_hash = hashlib.sha256(raw_data).hexdigest()[:16]
        self._metadata['prefix_hash'] = computed_prefix_hash
        self._metadata['integrity'] = 'verified'

        return self._metadata

    def cleanup(self):
        for name, buf in self._stage_buffers.items():
            buf.release()
        self._stage_buffers.clear()

    @staticmethod
    def _check_magic_bytes(header):
        png_magic = b'\x89PNG\r\n\x1a\n'
        jpg_magic = b'\xff\xd8\xff'
        gif_magic = b'GIF8'
        webp_magic = b'RIFF'

        return (header[:8] == png_magic or
                header[:3] == jpg_magic or
                header[:4] == gif_magic or
                header[:4] == webp_magic)


def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS


@app.route('/api/v1/upload', methods=['POST'])
def upload_image():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    safe_name = secure_filename(file.filename)
    raw_data = file.read()

    if len(raw_data) == 0:
        return jsonify({'error': 'Empty file'}), 400

    pipeline = ImageProcessingPipeline()

    try:
        if not pipeline.run_validation(raw_data):
            return jsonify({'error': 'Invalid image format'}), 400

        transformed = pipeline.run_transform(target_size=(1024, 768))
        metadata = pipeline.run_metadata_extraction()

        # Save transformed image
        upload_dir = os.path.join(tempfile.gettempdir(), 'uploads')
        os.makedirs(upload_dir, exist_ok=True)
        output_path = os.path.join(upload_dir, f"{metadata['hash'][:16]}_{safe_name}")

        with open(output_path, 'wb') as f:
            f.write(transformed)

        return jsonify({
            'status': 'success',
            'filename': safe_name,
            'metadata': metadata,
            'path': output_path
        }), 200

    except Exception:
        # Do not leak internal exception details to the client.
        logger.exception("Image processing failed")
        return jsonify({'error': 'Processing failed'}), 500

    finally:
        pipeline.cleanup()


@app.route('/api/v1/health', methods=['GET'])
def health_check():
    return jsonify({'status': 'healthy'}), 200


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000, debug=False)
